import { Controller } from "@hotwired/stimulus"
import { signedDifferenceInDays } from "helpers/date_helpers"

const REFRESH_INTERVAL = 3_600_000 // 1 hour (in milliseconds)

export default class extends Controller {
  static targets = [ "entropy", "top", "center", "bottom" ]
  static values = { options: Object }

  #timer

  connect() {
    this.#timer = setInterval(this.update.bind(this), REFRESH_INTERVAL)
    this.update()
  }

  disconnect() {
    clearInterval(this.#timer)
  }

  update() {
    if (this.#isStalled) {
      this.#showStalled()
    } else if (this.#hasEntropy) {
      this.#showEntropy()
    } else {
      this.#hide()
    }
  }

  get #isStalled() {
    return this.optionsValue.stalledSince != null && this.#stalledForInDays >= this.optionsValue.stalledAfterDays
  }

  get #stalledForInDays() {
    return signedDifferenceInDays(new Date(this.optionsValue.stalledSince), new Date())
  }

  #showStalled() {
    const days = this.#stalledForInDays

    this.#render({
      top: "Stalled for",
      center: days,
      bottom: days === 1 ? "day" : "days"
    })
  }

  get #hasEntropy() {
    return this.#entropyCleanupInDays < this.optionsValue.daysBeforeReminder
  }

  get #entropyCleanupInDays() {
    return signedDifferenceInDays(new Date(), new Date(this.optionsValue.closesAt))
  }

  #showEntropy() {
    const days = this.#entropyCleanupInDays

    this.#render({
      top: days < 1 ? this.optionsValue.action : `${this.optionsValue.action} in`,
      center: days < 1 ? "!" : days,
      bottom: days < 1 ? "Today" : (days === 1 ? "day" : "days"),
    })
  }

  #render({ top, center, bottom }) {
    this.topTarget.innerHTML = top
    this.centerTarget.innerHTML = center
    this.bottomTarget.innerHTML = bottom

    this.#show()
  }

  #hide() {
    this.element.toggleAttribute("hidden", true)
  }

  #show() {
    this.element.removeAttribute("hidden")
  }
}
EOF
