require "test_helper"

class EntropyHelperTest < ActionView::TestCase
  test "bubble options count down to the board closing the card" do
    card = cards(:layout)

    assert_equal({ daysBeforeReminder: card.entropy.days_before_reminder, closesAt: card.entropy.auto_clean_at.iso8601, action: "Closes" }, bubble_options_for(card))
  end

  test "bubble options carry the stall of a bursted card" do
    card = cards(:layout).tap do |card|
      card.update! bursted_at: 3.weeks.ago
    end

    assert_equal({ daysBeforeReminder: card.entropy.days_before_reminder, closesAt: card.entropy.auto_clean_at.iso8601, action: "Closes", stalledSince: card.last_active_at.iso8601, stalledAfterDays: 14 }, bubble_options_for(card))
  end
end
EOF
